INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Google Ads Trafiğiniz Üzerinde Daha Fazla Kontrol','home','<div class="ag-hero"><span class="ag-eyebrow">GOOGLE ADS TRAFİK GÜVENLİĞİ</span><h1>Reklam trafiğinizi daha yakından tanıyın.</h1><p class="ag-lead">AdGuard Pro, web sitenize gelen ziyaretleri anlamlandırmanıza, olağan dışı trafik davranışlarını incelemenize ve IP yönetimini tek bir kontrol panelinden yürütmenize yardımcı olur.</p><div class="ag-actions"><a class="ag-button" href="/register">Ücretsiz hesap oluştur</a><a class="ag-button ag-button-light" href="/page?slug=nasil-calisir">Nasıl çalıştığını keşfet</a></div><p class="ag-note">Veriye dayalı görünürlük. Kontrollü kararlar. Daha düzenli trafik yönetimi.</p></div>
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('AdGuard Pro Özellikleri','ozellikler','<div class="ag-page-intro"><span class="ag-eyebrow">ÜRÜN ÖZELLİKLERİ</span><h1>İhtiyacınız olan trafik görünürlüğü, tek panelde.</h1><p class="ag-lead">AdGuard Pro; ziyaret verilerini incelemek, şüpheli davranışları değerlendirmek ve IP yönetimini düzenli yürütmek için tasarlanmış bir trafik analiz platformudur.</p></div><section class="ag-grid ag-grid-2"><article class="ag-card"><h2>Ziyaret takibi ve analiz</h2><p>Web sitenize eklediğiniz takip kodu üzerinden gelen olayları merkezi panelde görüntüleyin. Ziyaret zamanı, IP bilgisi, sayfa adresi ve tarayıcı bilgisi gibi mevcut kayıt alanlarını inceleyin.</p></article><article class="ag-card"><h2>Risk puanlama ve nedenler</h2><p>Sistem tarafından riskli olarak işaretlenen ziyaretleri risk seviyesi ve tespit nedenleriyle değerlendirin. Puanlama, inceleme için bir sinyaldir; tek başına kötü niyetin kesin kanıtı değildir.</p></article><article class="ag-card"><h2>IP kural merkezi</h2><p>IP adresleri için izin, engelleme veya inceleme adayı kuralları oluşturun. Kuralları ilgili web sitesiyle ilişkilendirerek hangi işlem nerede uygulanıyor takip edin.</p></article><article class="ag-card"><h2>Google Ads hesap bağlantısı</h2><p>Google hesabı bağlantısı, müşteri kimliği ve kampanya görünümü gibi desteklenen entegrasyon alanlarını panelden yönetin. Kullanılabilir işlemler Google Ads API izinlerine ve hesap yapılandırmasına bağlıdır.</p></article><article class="ag-card"><h2>Çoklu site yönetimi</h2><p>Birden fazla web sitenizi aynı hesap altında toplayın. Paketinizde tanımlı site sınırını ve her sitenin ziyaret akışını ayrı ayrı takip edin.</p></article><article class="ag-card"><h2>Abonelik ve kullanım takibi</h2><p>Aktif planınızı, günlük ziyaret limitinizi, web sitesi sınırınızı ve abonelik durumunuzu müşteri panelinden görüntüleyin.</p></article><article class="ag-card"><h2>İşlem geçmişi</h2><p>Ziyaret kayıtları ve IP kural durumları üzerinden geçmişteki hareketleri inceleyin. Böylece kararlarınızı yalnızca anlık görüntüye göre vermek zorunda kalmazsınız.</p></article><article class="ag-card"><h2>Yönetici kontrolü</h2><p>Yönetim panelinden müşteri hesaplarını, paketleri, abonelikleri, sayfaları ve site menülerini yönetin.</p></article></section><section class="ag-callout"><h2>Teknoloji kararın yerini almaz, kararını destekler.</h2><p>Her risk göstergesini ziyaretin bağlamı, kendi reklam politikalarınız ve Google Ads kuralları çerçevesinde değerlendirmenizi öneririz.</p><a href="/page?slug=nasil-calisir">Çalışma adımlarını görüntüleyin →</a></section>','published','AdGuard Pro Özellikleri | AdGuard Pro','AdGuard Pro ziyaret analizi, risk göstergeleri, IP kural yönetimi, Google Ads bağlantısı ve çoklu web sitesi özellikleri.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('AdGuard Pro Nasıl Çalışır?','nasil-calisir','<div class="ag-page-intro"><span class="ag-eyebrow">BAŞLANGIÇ REHBERİ</span><h1>AdGuard Pro nasıl çalışır?</h1><p class="ag-lead">Hesap oluşturmadan ilk ziyaret kayıtlarını incelemeye kadar temel süreç birkaç anlaşılır adımdan oluşur.</p></div><div class="ag-timeline"><article class="ag-timeline-item"><b>01</b><div><h2>Hesabınızı oluşturun</h2><p>Kayıt sayfasından müşteri hesabınızı açın. İhtiyacınıza uygun abonelik planını seçerek panelinize erişin.</p></div></article><article class="ag-timeline-item"><b>02</b><div><h2>Web sitenizi kaydedin</h2><p>Müşteri panelindeki web sitesi ekleme alanından site adınızı ve alan adınızı girin. Sistem sitenize özel bir takip anahtarı oluşturur.</p></div></article><article class="ag-timeline-item"><b>03</b><div><h2>Takip kodunu yayınlayın</h2><p>Panelde sunulan takip kodunu web sitenizin uygun alanına ekleyin. Kodun doğru yüklendiğini ve tarayıcı tarafından engellenmediğini kontrol edin.</p></div></article><article class="ag-timeline-item"><b>04</b><div><h2>Ziyaretleri inceleyin</h2><p>Veri geldikçe ziyaret ekranından kayıtları, sayfa adreslerini ve mevcut risk göstergelerini inceleyin. İlk verilerin görünmesi trafik hacmine ve kurulum doğruluğuna bağlıdır.</p></div></article><article class="ag-timeline-item"><b>05</b><div><h2>IP kurallarını yönetin</h2><p>İnceleme sonucunda gerekli gördüğünüz IP adresleri için izin veya engelleme kuralları oluşturun. Otomatik tespitleri mutlaka kendi ölçütlerinizle değerlendirin.</p></div></article><article class="ag-timeline-item"><b>06</b><div><h2>Google Ads bağlantınızı yapılandırın</h2><p>Google bağlantı ekranından hesabınızı yetkilendirin. Entegrasyonun kullanılabilirliği Google tarafındaki API erişimi, izinler ve hesap ayarlarına bağlıdır.</p></div></article></div><section class="ag-callout"><h2>Kurulumda yardıma mı ihtiyacınız var?</h2><p>Takip kodunun sitenizde doğru çalıştığını doğrulayın; güvenlik eklentileri, önbellek ve içerik güvenlik politikaları kodun yüklenmesini etkileyebilir.</p><a href="/register">Hesap oluşturun →</a></section>','published','AdGuard Pro Nasıl Çalışır? | AdGuard Pro','AdGuard Pro kurulumu, web sitesi takip kodu, ziyaret analizi ve IP yönetimi adımları.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Sıkça Sorulan Sorular','sss','<div class="ag-page-intro"><span class="ag-eyebrow">YARDIM MERKEZİ</span><h1>Sıkça sorulan sorular</h1><p class="ag-lead">AdGuard Pro''yu kullanmaya başlamadan önce merak edebileceğiniz temel konuların yanıtları.</p></div><div class="ag-faq"><article><h2>AdGuard Pro ne işe yarar?</h2><p>Web sitenize gelen ziyaretleri izlemenize, risk göstergelerini incelemenize ve IP kural yönetimini tek panelden yürütmenize yardımcı olur.</p></article><article><h2>AdGuard Pro tüm sahte tıklamaları engeller mi?</h2><p>Hiçbir trafik analiz sistemi tüm geçersiz veya kötü niyetli trafiği kesin olarak tespit edip engelleme garantisi veremez. AdGuard Pro mevcut sinyalleri görünür kılar ve inceleme/aksiyon süreçlerinizi destekler.</p></article><article><h2>Takip kodunu nereye eklemeliyim?</h2><p>Web sitesi ekleme ekranında sunulan kodu, sitenizin tüm izlenmesini istediğiniz sayfalarında çalışacak uygun alana yerleştirin. Yayına aldıktan sonra ilk ziyaret kaydını kontrol edin.</p></article><article><h2>Birden fazla web sitesi ekleyebilir miyim?</h2><p>Evet. Ekleyebileceğiniz site sayısı seçtiğiniz abonelik planındaki web sitesi limitiyle sınırlıdır.</p></article><article><h2>Risk puanı ziyaretin kesinlikle bot olduğunu gösterir mi?</h2><p>Hayır. Risk puanı ve tespit nedenleri değerlendirme sinyalleridir. Yanlış pozitifleri önlemek için IP engellemeden önce ziyaret bağlamını inceleyin.</p></article><article><h2>Google Ads hesabımı bağlamak zorunda mıyım?</h2><p>Hayır. Temel ziyaret analizi ve IP yönetimi için Google Ads bağlantısı zorunlu değildir. Entegrasyon özelliklerini kullanmak isterseniz hesabınızı yetkilendirebilirsiniz.</p></article><article><h2>Google Ads üzerinden otomatik işlem yapılır mı?</h2><p>Bağlantı ve hesap izinlerine göre desteklenen kampanya/IP işlemleri kullanılabilir. Google Ads API kısıtları ve hesap yetkileri geçerlidir; her işlem öncesinde paneldeki durumu kontrol edin.</p></article><article><h2>Aboneliğim otomatik yenilenir mi?</h2><p>Otomatik yenileme yalnızca ödeme akışında açıkça seçip onayladığınız ve desteklenen abonelik yöntemlerinde etkinleştirilir. Yenileme tercihinizi ödeme ve abonelik ekranlarından kontrol edin.</p></article><article><h2>Aboneliğimi nasıl iptal edebilirim?</h2><p>Desteklenen aboneliklerde müşteri panelindeki abonelik/yenileme işlemlerini kullanın. İptal koşulları ve dönem sonu erişimi için İade ve İptal Politikası sayfasını inceleyin.</p></article><article><h2>Verilerim ne kadar süre saklanır?</h2><p>Saklama süreleri hizmetin güncel veri saklama politikasına ve işletmecinin yapılandırmasına bağlıdır. Yayınlanan Gizlilik ve KVKK metinlerinde belirtilen süreleri esas alın.</p></article><article><h2>Teknik destek nasıl alabilirim?</h2><p>Hizmet sağlayıcısının bu sitede yayınladığı güncel iletişim kanalını kullanın. İletişim sayfasındaki bilgiler işletmeci tarafından güncel tutulmalıdır.</p></article></div>','published','Sıkça Sorulan Sorular | AdGuard Pro','AdGuard Pro hakkında hesap, takip kodu, ziyaret analizi, IP kuralları, Google Ads bağlantısı ve abonelik soruları.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Hakkımızda','hakkimizda','<div class="ag-page-intro"><span class="ag-eyebrow">HAKKIMIZDA</span><h1>Daha anlaşılır trafik verisi, daha bilinçli kararlar.</h1><p class="ag-lead">AdGuard Pro, web sitesi ziyaretlerini ve IP yönetimini tek bir çalışma alanında birleştirmek amacıyla geliştirilmiş bir trafik analiz platformudur.</p></div><section class="ag-prose"><h2>Yaklaşımımız</h2><p>Dijital reklam kampanyalarının sağlıklı değerlendirilmesi, yalnızca tıklama sayısına bakmaktan fazlasını gerektirir. Web sitesine gelen ziyaretlerin niteliğini anlamak, olağan dışı davranışları fark etmek ve alınan aksiyonları kayıt altında tutmak önemlidir.</p><p>AdGuard Pro; ziyaret takibi, risk göstergeleri, IP kural yönetimi ve desteklenen Google Ads bağlantı iş akışlarını aynı panelde sunarak bu süreci daha düzenli hale getirmeyi hedefler.</p><h2>Şeffaf ve kontrollü kullanım</h2><p>Analiz sonuçları karar desteği sağlar; kesin hüküm veya reklam performansı garantisi değildir. Kullanıcıların verileri bağlamıyla değerlendirmesini, platformu yürürlükteki mevzuata ve ilgili reklam platformlarının politikalarına uygun kullanmasını önemseriz.</p><h2>Ürün geliştirme anlayışı</h2><p>Yönetim, müşteri hesapları, paketler, abonelikler ve içerik yönetiminin tek merkezden yürütülebilmesi için sürekli geliştirilebilir bir altyapı hedefliyoruz.</p></section>','published','Hakkımızda | AdGuard Pro','AdGuard Pro''nun amacı, yaklaşımı ve dijital reklam trafiği yönetimine bakışı.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('İletişim','iletisim','<div class="ag-page-intro"><span class="ag-eyebrow">İLETİŞİM</span><h1>Size yardımcı olmak için buradayız.</h1><p class="ag-lead">AdGuard Pro hesabınız, aboneliğiniz veya teknik kullanımınızla ilgili sorularınız için hizmet sağlayıcısının yayınladığı iletişim kanalını kullanabilirsiniz.</p></div><div class="ag-grid ag-grid-2"><article class="ag-card"><h2>Teknik destek</h2><p>Takip kodu kurulumu, ziyaret kayıtları, IP kural yönetimi veya Google Ads bağlantısıyla ilgili destek taleplerinizde karşılaştığınız adımları ve mümkünse hata mesajını paylaşın.</p></article><article class="ag-card"><h2>Abonelik ve ödeme</h2><p>Paket, ödeme, fatura, yenileme ve iptal konularındaki taleplerinizde hesabınızla ilişkili e-posta adresini ve işlem tarihini belirtin. Kart numarası veya güvenlik kodu gibi hassas ödeme bilgilerini mesajla göndermeyin.</p></article></div><section class="ag-callout"><h2>İşletmeci iletişim bilgileri</h2><p>Hizmeti sunan şirketin ticari unvanı, destek e-posta adresi, telefon numarası ve varsa fiziksel adresi bu bölümde yayınlanmalıdır. Bu bilgileri yönetim panelindeki sayfa düzenleyicisinden gerçek bilgilerinizle güncelleyin.</p></section>','published','İletişim | AdGuard Pro','AdGuard Pro hizmeti, abonelik ve teknik destek konularında iletişim bilgileri.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Gizlilik Politikası','privacy','<div class="ag-page-intro"><span class="ag-eyebrow">YASAL BİLGİLENDİRME</span><h1>Gizlilik Politikası</h1><p class="ag-lead">Bu metin, AdGuard Pro hizmetinin kullanımı sırasında kişisel verilerin ve teknik kayıtların nasıl ele alınabileceğini açıklayan genel bir taslaktır.</p></div><section class="ag-prose"><h2>1. Veri sorumlusu</h2><p>Hizmetin veri sorumlusu: [ŞİRKETİN TİCARİ UNVANI]. İletişim: [GÜNCEL E-POSTA VE ADRES]. Bu alanlar yayın öncesinde gerçek bilgilerle doldurulmalıdır.</p><h2>2. İşlenebilecek bilgiler</h2><p>Hesap oluşturma ve hizmet sunumu kapsamında ad, e-posta adresi, parola özeti, abonelik ve ödeme işlem referansları; web sitesi entegrasyonu kapsamında IP adresi, ziyaret zamanı, sayfa adresi, tarayıcı bilgisi, yönlendiren adres ve risk değerlendirme kayıtları işlenebilir. Google hesabı bağlantısı kurulursa yetkilendirme kapsamında gerekli hesap ve token bilgileri de işlenebilir.</p><h2>3. İşleme amaçları</h2><p>Bu bilgiler hesap yönetimi, hizmetin sunulması, ziyaret analizi, güvenlik ve kötüye kullanımın önlenmesi, IP kurallarının yönetimi, abonelik/ödeme süreçleri, teknik destek, hata giderme ve hukuki yükümlülüklerin yerine getirilmesi amaçlarıyla kullanılabilir.</p><h2>4. Hukuki sebepler</h2><p>Veriler, somut işleme faaliyetine göre sözleşmenin kurulması veya ifası, veri sorumlusunun hukuki yükümlülüğü, bir hakkın tesisi/kullanılması/korunması, meşru menfaat veya gerektiğinde açık rıza hukuki sebeplerine dayanılarak işlenir. Her faaliyet için uygun hukuki sebep ayrıca belirlenmelidir.</p><h2>5. Paylaşım ve hizmet sağlayıcıları</h2><p>Veriler; barındırma, altyapı, güvenlik, e-posta, ödeme ve Google entegrasyonu gibi hizmetlerin sunulması için gerekli ölçüde ilgili tedarikçilerle paylaşılabilir. Kanunen yetkili kamu kurumlarının usulüne uygun talepleri ayrıca değerlendirilir.</p><h2>6. Saklama ve güvenlik</h2><p>Veriler, işleme amacının gerektirdiği süre ve ilgili mevzuattaki zamanaşımı/saklama yükümlülükleri boyunca tutulur. Erişim kontrolü, parola güvenliği, yedekleme ve teknik/idari tedbirler uygulanmalıdır. Gerçek saklama süreleri işletmeci tarafından belirlenip bu metne eklenmelidir.</p><h2>7. Kullanıcı hakları ve başvuru</h2><p>İlgili kişiler, yürürlükteki mevzuat kapsamında kendileriyle ilgili veriler hakkında bilgi talep etme, düzeltme, silme veya işlemeye itiraz etme gibi haklarını kullanabilir. Başvuru yöntemi ve yetkili iletişim kanalı işletmeci tarafından burada açıklanmalıdır.</p><h2>8. Politika değişiklikleri</h2><p>Hizmetin işleyişi veya mevzuat değiştikçe bu politika güncellenebilir. Güncel metin web sitesinde yayınlandığı tarihten itibaren geçerli olur.</p><p><strong>Önemli:</strong> Bu taslak hukuki danışmanlık değildir. Gerçek veri akışları, tedarikçiler, saklama süreleri ve yurt dışı aktarım ihtimalleri doğrulanmadan yayınlanmamalıdır.</p></section>','published','Gizlilik Politikası | AdGuard Pro','AdGuard Pro kullanıcı verilerinin işlenmesi, güvenliği, paylaşımı ve saklanmasına ilişkin gizlilik politikası taslağı.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('KVKK Aydınlatma Metni','kvkk','<div class="ag-page-intro"><span class="ag-eyebrow">6698 SAYILI KANUN KAPSAMINDA</span><h1>Kişisel Verilerin İşlenmesine İlişkin Aydınlatma Metni</h1><p class="ag-lead">Bu metin, AdGuard Pro hizmeti kapsamında kişisel verilerin işlenmesine yönelik düzenlenmesi gereken başlıkları içerir.</p></div><section class="ag-prose"><h2>1. Veri sorumlusunun kimliği</h2><p>Veri sorumlusu: [ŞİRKETİN TİCARİ UNVANI]. Adres: [ŞİRKET ADRESİ]. Başvuru e-postası: [KVKK BAŞVURU E-POSTASI].</p><h2>2. İşlenen kişisel veri kategorileri</h2><p>Kimlik ve iletişim bilgileri; müşteri işlem ve abonelik bilgileri; işlem güvenliği kayıtları; web sitesi ziyaretleri kapsamında IP adresi, zaman damgası, tarayıcı ve sayfa bilgileri; Google bağlantısı kurulması halinde entegrasyon için gerekli hesap/işlem verileri işlenebilir.</p><h2>3. İşleme amaçları</h2><p>Hesap ve müşteri ilişkilerinin yürütülmesi, hizmetin sağlanması, ziyaret ve risk analizi, IP kural yönetimi, bilgi güvenliği, ödeme ve abonelik işlemleri, destek faaliyetleri ve hukuki yükümlülüklerin yerine getirilmesi amaçlanır.</p><h2>4. Kişisel verilerin aktarılması</h2><p>Veriler, hizmetin gerektirdiği ölçüde barındırma ve altyapı sağlayıcılarına, ödeme kuruluşlarına, entegrasyon sağlayıcılarına, profesyonel danışmanlara ve kanunen yetkili kurumlara aktarılabilir. Alıcı grupları ve aktarım ülkeleri gerçek hizmet mimarisine göre açıkça belirtilmelidir.</p><h2>5. Toplama yöntemi ve hukuki sebepler</h2><p>Veriler; web sitesi kayıt ve formları, müşteri paneli, takip kodu, ödeme/abonelik altyapısı ve entegrasyonlar aracılığıyla elektronik ortamda toplanabilir. İşleme faaliyetinin niteliğine göre KVKK''nın 5. ve ilgili hallerde 6. maddesindeki uygun hukuki sebepler esas alınır.</p><h2>6. İlgili kişinin hakları</h2><p>İlgili kişiler, KVKK''nın 11. maddesinde sayılan hakları kapsamında veri işlenip işlenmediğini öğrenme, bilgi talep etme, amaca uygun kullanım ve aktarım bilgisi edinme, eksik/yanlış verilerin düzeltilmesini ve kanuni şartlarda silinmesini/yok edilmesini isteme, otomatik analiz sonuçlarına itiraz etme ve kanuni şartlarda zararının giderilmesini talep etme haklarına sahiptir.</p><h2>7. Başvuru usulü</h2><p>Başvurular [BAŞVURU ADRESİ / KEP / E-POSTA VE KİMLİK DOĞRULAMA YÖNTEMİ] üzerinden alınır. Başvurular mevzuattaki usul ve süreler içinde yanıtlanır.</p><p><strong>Yayın öncesi kontrol:</strong> Veri sorumlusu bilgileri, gerçek veri kategorileri, hukuki sebepler, alıcı grupları, yurt dışı aktarım durumu, saklama süreleri ve başvuru kanalı mutlaka doğrulanmalıdır. Bu metin hukuki danışmanlık yerine geçmez.</p></section>','published','KVKK Aydınlatma Metni | AdGuard Pro','AdGuard Pro kapsamında kişisel verilerin işlenmesine ilişkin KVKK aydınlatma metni taslağı.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Çerez Politikası','cerez-politikasi','<div class="ag-page-intro"><span class="ag-eyebrow">ÇEREZLER VE BENZERİ TEKNOLOJİLER</span><h1>Çerez Politikası</h1><p class="ag-lead">Bu politika, web sitesinde kullanılan çerezlerin amaçlarını ve kullanıcıların tercihlerini nasıl yönetebileceğini açıklar.</p></div><section class="ag-prose"><h2>1. Çerez nedir?</h2><p>Çerezler, ziyaret ettiğiniz web sitesi tarafından tarayıcınızda saklanan küçük metin dosyalarıdır. Oturumun sürdürülmesi, güvenlik, tercihlerin hatırlanması ve izin verilmesi halinde analiz gibi amaçlarla kullanılabilirler.</p><h2>2. Kullanılabilecek çerez kategorileri</h2><p><strong>Zorunlu çerezler:</strong> Oturum açma, güvenlik ve temel site işlevleri için gerekli olabilir.</p><p><strong>Tercih çerezleri:</strong> Dil veya kullanıcı tercihlerinin hatırlanmasını sağlayabilir.</p><p><strong>Analitik çerezler:</strong> Ziyaret ve kullanım eğilimlerini anlamak için kullanılabilir; gerekli hallerde izin alınmalıdır.</p><p><strong>Pazarlama çerezleri:</strong> Reklam ölçümü veya kişiselleştirme amacıyla kullanılabilir; uygulanıyorsa uygun izin mekanizması kurulmalıdır.</p><h2>3. Çerez tercihleri</h2><p>Tarayıcı ayarlarınızdan çerezleri engelleyebilir veya silebilirsiniz. Zorunlu çerezlerin devre dışı bırakılması giriş ve güvenlik gibi temel işlevlerin çalışmasını etkileyebilir.</p><h2>4. Üçüncü taraflar</h2><p>Ödeme, güvenlik, analiz veya entegrasyon sağlayıcıları kendi teknolojilerini kullanabilir. Gerçek sağlayıcı listesi, çerez adları, amaçları ve saklama süreleri işletmeci tarafından güncel bir çerez envanterine göre eklenmelidir.</p><h2>5. Güncellemeler</h2><p>Çerez kullanımı veya mevzuat değiştiğinde politika güncellenebilir.</p><p><strong>Yayın öncesi:</strong> Sitede gerçekten kullanılan çerezleri tarayıcı ve uygulama envanteriyle doğrulayın; kullanılmayan kategorileri kaldırın ve gerekiyorsa çerez tercih paneli ekleyin.</p></section>','published','Çerez Politikası | AdGuard Pro','AdGuard Pro web sitesinde çerez ve benzeri teknolojilerin kullanımına ilişkin politika taslağı.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('Kullanım Şartları','kullanim-sartlari','<div class="ag-page-intro"><span class="ag-eyebrow">HİZMET KOŞULLARI</span><h1>Kullanım Şartları</h1><p class="ag-lead">AdGuard Pro platformuna erişerek bu hizmet koşullarını kabul etmiş olursunuz. Hizmeti kullanmadan önce metni dikkatle inceleyin.</p></div><section class="ag-prose"><h2>1. Hizmetin kapsamı</h2><p>AdGuard Pro; web sitesi ziyaretlerinin izlenmesi, trafik göstergelerinin incelenmesi, IP kural yönetimi ve sunulan plana göre entegrasyon/raporlama araçları sağlar. Özellikler teknik gerekliliklere ve seçilen pakete göre değişebilir.</p><h2>2. Hesap güvenliği</h2><p>Kullanıcı, kayıt sırasında doğru bilgi vermek, giriş bilgilerini korumak ve hesabı üzerinden gerçekleşen işlemleri takip etmekle yükümlüdür. Yetkisiz erişim şüphesinde hizmet sağlayıcısına gecikmeden bildirim yapılmalıdır.</p><h2>3. Hukuka ve platform politikalarına uygun kullanım</h2><p>Kullanıcı, takip kodunu yalnızca gerekli yetkilere sahip olduğu web sitelerinde kullanır; kişisel verilerin işlenmesi, çerezler, reklam ölçümü ve IP işlemleri bakımından yürürlükteki mevzuata ve üçüncü taraf platform koşullarına uyar.</p><h2>4. Analiz sonuçları ve sorumluluk</h2><p>Risk puanları ve tespit sinyalleri otomatik analiz çıktılarıdır; bir ziyaretin sahte, zararlı veya geçersiz olduğuna ilişkin kesin hukuki/teknik hüküm oluşturmaz. Kullanıcı, engelleme ve reklam hesabı işlemlerini uygulamadan önce sonuçları değerlendirir. Belirli reklam performansı, dönüşüm, gelir veya tüm kötü niyetli trafiğin engelleneceği garanti edilmez.</p><h2>5. Abonelik ve ödeme</h2><p>Ücret, dönem, limit ve özellikler satın alma sırasında gösterilen paket bilgilerine göre belirlenir. Otomatik yenileme yalnızca kullanıcının açıkça seçip onayladığı desteklenen ödeme akışlarında uygulanır. İptal ve iade koşulları ayrı politikada açıklanır.</p><h2>6. Hizmetin kullanılabilirliği</h2><p>Bakım, güvenlik, üçüncü taraf servisleri, internet altyapısı veya mücbir sebepler nedeniyle geçici kesinti yaşanabilir. Hizmet sağlayıcısı kesintileri azaltmak için makul teknik çabayı gösterir.</p><h2>7. Fikri mülkiyet</h2><p>Platformun yazılımı, tasarımı, markası ve dokümantasyonu üzerindeki haklar ilgili hak sahiplerine aittir. Kullanıcıya yalnızca abonelik süresince ve koşullara uygun kullanım hakkı verilir.</p><h2>8. Hesabın sınırlandırılması</h2><p>Şartların ihlali, güvenlik riski, hukuka aykırı kullanım veya ödeme yükümlülüklerinin yerine getirilmemesi halinde mevzuata ve sözleşmeye uygun olarak erişim sınırlandırılabilir.</p><h2>9. Değişiklikler ve iletişim</h2><p>Koşullar güncellenebilir. Hizmet sağlayıcısının unvanı, adresi ve iletişim kanalı: [İŞLETMECİ BİLGİLERİ].</p><p><strong>Not:</strong> Bu metin genel bir sözleşme taslağıdır. İş modeliniz, tüketici hukuku yükümlülükleri, sorumluluk sınırları ve ödeme süreçleri için hukuk danışmanı tarafından gözden geçirilmelidir.</p></section>','published','Kullanım Şartları | AdGuard Pro','AdGuard Pro platformunun kullanımı, hesap sorumlulukları, hizmet sınırları ve fikri mülkiyet koşulları.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
INSERT INTO pages (title,slug,content,status,meta_title,meta_description) VALUES ('İade ve İptal Politikası','iade-iptal','<div class="ag-page-intro"><span class="ag-eyebrow">ABONELİK VE ÖDEME</span><h1>İade ve İptal Politikası</h1><p class="ag-lead">Abonelik dönemleri, yenileme tercihi ve iptal başvurularının nasıl ele alındığına ilişkin genel bilgilendirme.</p></div><section class="ag-prose"><h2>1. Abonelik dönemi</h2><p>Satın alınan planın süresi, fiyatı, kullanım limitleri ve özellikleri ödeme öncesinde gösterilir. Abonelik, ödeme sağlayıcısından gelen başarılı işlem bildirimi ve sistemdeki aktivasyon koşulları doğrultusunda başlatılır.</p><h2>2. Otomatik yenileme</h2><p>Otomatik yenileme varsayılan olarak kullanıcı adına seçilmiş kabul edilmez. Yalnızca ödeme akışında açıkça seçilip onaylanan ve desteklenen abonelik yöntemlerinde etkinleştirilir. Kullanıcı, ödeme öncesinde yenileme koşullarını kontrol etmelidir.</p><h2>3. İptal</h2><p>Kullanıcı, desteklenen aboneliklerde müşteri panelinden yenileme/iptal işlemi yapabilir. Yenilemenin iptali, aksi ayrıca belirtilmedikçe mevcut ödenmiş dönemin kendiliğinden iade edilmesi anlamına gelmez; erişimin dönem sonuna kadar sürüp sürmeyeceği satın alınan plana ve yürürlükteki mevzuata göre belirlenir.</p><h2>4. İade talepleri</h2><p>İade talepleri, ödeme yöntemi, hizmetin kullanıma başlanıp başlanmadığı, işlem hatası, ilgili sözleşme ve tüketici mevzuatı dikkate alınarak ayrı ayrı değerlendirilir. Kanundan doğan emredici tüketici hakları saklıdır.</p><h2>5. Hatalı veya mükerrer ödeme</h2><p>Hatalı, mükerrer veya yetkisiz olduğu düşünülen işlemler için ödeme tarihi, işlem referansı ve hesap e-posta adresiyle destek kanalına başvurulmalıdır. Kart numarası, CVV veya tek kullanımlık şifre paylaşılmamalıdır.</p><h2>6. Başvuru kanalı</h2><p>İptal ve iade başvuruları: [DESTEK E-POSTASI / BAŞVURU ADRESİ]. İşletmeci unvanı ve iletişim bilgileri: [ŞİRKET BİLGİLERİ].</p><p><strong>Yayın öncesi:</strong> Gerçek ödeme sağlayıcı sözleşmeleri, abonelik akışı ve tüketici mevzuatıyla uyumlu hale getirilmeden bu taslak nihai politika olarak kullanılmamalıdır.</p></section>','published','İade ve İptal Politikası | AdGuard Pro','AdGuard Pro abonelik iptali, otomatik yenileme ve iade taleplerine ilişkin politika taslağı.') ON DUPLICATE KEY UPDATE status=IF(content IS NULL OR content='','published',status), content=IF(content IS NULL OR content='',VALUES(content),content), meta_title=IF(meta_title IS NULL OR meta_title='',VALUES(meta_title),meta_title), meta_description=IF(meta_description IS NULL OR meta_description='',VALUES(meta_description),meta_description);
